import re

PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$")

def run_pipeline(raw):
    seen = set()
    rejected = duplicates = 0
    by_type = {}
    for r in raw:
        if not r.get("user") or not PATTERN.match(str(r.get("event_ts") or "")):
            rejected += 1
            continue
        if r["event_id"] in seen:
            duplicates += 1
            continue
        seen.add(r["event_id"])
        by_type[r["type"]] = by_type.get(r["type"], 0) + 1
    return {"loaded": len(seen), "rejected": rejected, "duplicates": duplicates, "by_type": by_type}

